//! Selected deletion uses genuine inert native mutation producers.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://inert-delete.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var parsed=new DOMParser().parseFromString('<body><template id=t><b>A😀B</b><span>Middle</span><em>End</em></template></body>','text/html'),root=parsed.getElementById('t').content,owner=root.ownerDocument,first=root.firstChild.firstChild,middle=root.childNodes[1],last=root.lastChild.firstChild,r=owner.createRange();r.setStart(first,1);r.setEnd(last,2);var remove=r.deleteContents;");(d,f,p)}
#[test]
fn range_inert_deletion_partial_ancestors_topmost_selected_nodes_and_document_children(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(r.deleteContents()!==undefined||root.textContent!=='Ad'||root.childNodes.length!==2||root.firstChild.firstChild!==first||root.lastChild.firstChild!==last||middle.parentNode!==null||middle.ownerDocument!==owner||middle.textContent!=='Middle'||!r.collapsed||r.startContainer!==root||r.startOffset!==1)throw 'native selected inert deletion and collapse';
var doc=document.implementation.createHTMLDocument('Delete'),type=doc.doctype,html=doc.documentElement,whole=doc.createRange();whole.selectNodeContents(doc);whole.deleteContents();if(doc.childNodes.length||doc.doctype!==null||doc.documentElement!==null||type.parentNode!==null||html.parentNode!==null||type.ownerDocument!==doc||!whole.collapsed||whole.startContainer!==doc||whole.startOffset)throw 'genuine inert Document children and metadata synchronization';
"#);assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.has_navigation_request());}
#[test]
fn range_inert_deletion_exact_character_kinds_collapsed_and_ancestor_boundaries(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var dataOwner=new Document();for(var node of [dataOwner.createTextNode('\uD800A\uDC00'),dataOwner.createCDATASection('\uD800A\uDC00'),dataOwner.createComment('\uD800A\uDC00'),dataOwner.createProcessingInstruction('target','\uD800A\uDC00')]){var selected=dataOwner.createRange();selected.setStart(node,1);selected.setEnd(node,2);selected.deleteContents();if(node.data.length!==2||node.data.charCodeAt(0)!==55296||node.data.charCodeAt(1)!==56320||!selected.collapsed||selected.startOffset!==1||selected.startContainer!==node||node.nodeType===7&&node.target!=='target')throw 'actual exact inert CharacterData deletion';selected.deleteContents();if(node.data.length!==2)throw 'collapsed deletion has no data effects';}
var edge=owner.createRange();edge.setStart(root,1);edge.setEnd(last,2);edge.deleteContents();if(root.textContent!=='A😀Bd'||middle.parentNode!==null||edge.startContainer!==root||edge.startOffset!==1||!edge.collapsed)throw 'ancestor start keeps unselected siblings';edge.setStart(first,2);edge.setEnd(root,2);edge.deleteContents();if(root.childNodes.length!==1||first.data.length!==2||first.data.charCodeAt(1)!==55357||edge.startContainer!==root||edge.startOffset!==1||!edge.collapsed)throw 'ancestor end and raw leading surrogate';
"#);}
#[test]
fn range_inert_deletion_real_observer_order_live_aliases_fixed_snapshots_and_iterator(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var obs=new MutationObserver(function(){throw 'records drained';});obs.observe(root,{subtree:true,childList:true,characterData:true,characterDataOldValue:true});var live=r.cloneRange(),fixed=new StaticRange({startContainer:first,startOffset:1,endContainer:last,endOffset:2}),inside=owner.createRange();inside.selectNodeContents(middle.firstChild);var iterator=owner.createNodeIterator(root);while(iterator.nextNode()!==middle){}r.deleteContents();var records=obs.takeRecords();if(records.length!==3||records[0].type!=='characterData'||records[0].target!==first||records[0].oldValue!=='A😀B'||records[1].type!=='childList'||records[1].target!==root||records[1].removedNodes[0]!==middle||records[1].previousSibling!==root.firstChild||records[1].nextSibling!==root.lastChild||records[2].target!==last||records[2].oldValue!=='End')throw 'ordered genuine inert mutation records';if(live.startContainer!==first||live.startOffset!==1||live.endContainer!==last||live.endOffset||inside.startContainer!==root||inside.startOffset!==1||!inside.collapsed||fixed.startContainer!==first||fixed.endContainer!==last||fixed.endOffset!==2||iterator.referenceNode===middle||iterator.nextNode()!==root.lastChild)throw 'actual inert live fixed and iterator effects';
"#);}
#[test]
fn range_inert_deletion_native_plan_work_copy_retained_deadline_refusal_and_recovery(){
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();p.begin_job();let before=(p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end,p.state.retained,p.state.inert_documents.backing_bytes());let limit=p.state.retained_limit;match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>{p.state.host_work=4096;p.state.execution_deadline=Some(Instant::now());}}assert!(p.runtime.execute("r.deleteContents()",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end,p.state.retained,p.state.inert_documents.backing_bytes()),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(root.textContent!=='A😀BMiddleEnd'||middle.parentNode!==root)throw 'inert plan refusal preserves native source';r.deleteContents();if(root.textContent!=='Ad'||!r.collapsed)throw 'fresh inert selected deletion recovery';");}
}
#[test]
fn range_inert_deletion_borrowed_method_realm_authority_loss_and_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,remove=w.Range.prototype.deleteContents,caught=false;try{remove.call({});}catch(e){caught=e instanceof w.TypeError;}if(!caught)throw 'canonical borrowed native deletion brand realm';");let before=(p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);p.set_location(&crate::navigation::address("https://other.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("remove.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!((p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);p.set_location(&crate::navigation::address("https://inert-delete.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"remove.call(r);if(root.textContent!=='Ad'||!r.collapsed)throw 'native borrowed inert deletion after authority recovery';");
}

#[test]
fn range_inert_deletion_late_data_refusal_keeps_specified_collapse_and_refunds_plan(){
 let(mut d,mut f,mut p)=fixture();p.begin_job();let before=p.state.dom_commits;let retained=p.state.retained;let copies=p.state.copy_work;
 let receiver=match p.runtime.execute("r",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap(){Value::Host(handle)=>handle,_=>panic!("native Range")};
 let plan=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.range_delete_plan(receiver).unwrap_or_else(|_|panic!("native inert deletion plan"));let bytes=plan.capacity()*size_of::<crate::javascript::range_interface::DeleteStep>();let cost=copies-p.state.copy_work;assert_eq!(p.state.retained,retained+bytes);p.state.retained-=bytes;drop(plan);p.begin_job();p.state.copy_work=cost;
 assert!(p.runtime.execute("remove.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(p.state.dom_commits,before);assert_eq!(p.state.retained,retained);
 run(&mut d,&mut f,&mut p,"if(root.textContent!=='A😀BMiddleEnd'||!r.collapsed||r.startContainer!==root||r.startOffset!==1)throw 'specified inert collapse survives later data refusal';r.setStart(first,1);r.setEnd(last,2);remove.call(r);if(root.textContent!=='Ad'||!r.collapsed)throw 'fresh inert late data recovery';");
}
#[test]
fn range_inert_deletion_late_removal_refusal_keeps_actual_data_prefix_and_live_state(){
 let(mut md,mut mf,mut mp)=fixture();mp.begin_job();let copies=mp.state.copy_work;mp.runtime.execute("first.deleteData(1,3)",&mut Bridge{doc:&mut md,forms:&mut mf,state:&mut mp.state}).unwrap();let prefix=copies-mp.state.copy_work;assert!(prefix>0);
 let(mut d,mut f,mut p)=fixture();p.begin_job();let receiver=match p.runtime.execute("r",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap(){Value::Host(handle)=>handle,_=>panic!("native Range")};let copies=p.state.copy_work;let plan=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.range_delete_plan(receiver).unwrap_or_else(|_|panic!("native inert deletion plan"));let bytes=plan.capacity()*size_of::<crate::javascript::range_interface::DeleteStep>();let cost=copies-p.state.copy_work;p.state.retained-=bytes;drop(plan);p.begin_job();p.state.copy_work=cost+prefix;let before=p.state.dom_commits;
 assert!(p.runtime.execute("remove.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!(p.state.dom_commits,before.map(|generation|generation+1));
 run(&mut d,&mut f,&mut p,"if(first.data!=='A'||middle.parentNode!==root||last.data!=='End'||!r.collapsed||r.startContainer!==root||r.startOffset!==1)throw 'actual inert data prefix survives later removal refusal';r.setStart(first,1);r.setEnd(last,2);remove.call(r);if(root.textContent!=='Ad'||!r.collapsed)throw 'fresh late inert removal recovery';");
}
